def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    s = data[1]

    result = [-1] * n

    for start in range(n):
        current_step = start + 1
        direction = s[start]
        seconds = 0

        while True:
            seconds += 1
            if direction == 'U':
                current_step += 1
            else:
                current_step -= 1

            if current_step < 1 or current_step > n:
                result[start] = seconds
                break

            if current_step == 1 and direction == 'D':
                result[start] = seconds
                break

            if current_step == n and direction == 'U':
                result[start] = seconds
                break

            direction = 'U' if direction == 'D' else 'D'

    print(' '.join(map(str, result)))

if __name__ == "__main__":
    main()
